/* Host-side compatibility exports used when the CUDA provider is preloaded.
 * Kept separate from the generated driver map so API regeneration remains
 * deterministic. */
libcublas.so.13 {
  global:
    cublasInit;
    cublasCreate_v2;
    cublasDestroy_v2;
    cublasGetVersion_v2;
    cublasSetPointerMode_v2;
    cublasGetPointerMode_v2;
    cublasSetStream_v2;
    cublasGetStream_v2;
    cublasSaxpy_v2;
    cublasDaxpy_v2;
    cublasSscal_v2;
    cublasDscal_v2;
    cublasScopy_v2;
    cublasDcopy_v2;
    cublasSdot_v2;
    cublasDdot_v2;
    cublasSnrm2_v2;
    cublasDnrm2_v2;
    cublasSasum_v2;
    cublasDasum_v2;
    cublasSgemv_v2;
    cublasDgemv_v2;
    cublasSgemm_v2;
    cublasDgemm_v2;
    cublasHgemm;
    cublasSgemmStridedBatched;
    cublasDgemmStridedBatched;
    cublasHgemmStridedBatched;
  local: *;
};
